-- ============================================================================
-- HR : อัปเดตทะเบียนพนักงาน (ชุดแก้ไข 2026-10-29) + ข้อมูล Passport / Visa / ใบอนุญาตทำงาน
--   1) เพิ่มคอลัมน์เอกสาร (passport_no, passport_exp, visa_exp, permit_type, wp_no, wp_exp, pink_no, pink_exp)
--   2) ทะเบียนลูกจ้าง UBG.xlsx : 314 คน (เพิ่ม / แก้ไข / ตั้งเป็น Active)
--   3) คนในกลุ่ม UBG / DMM / นักศึกษา ที่ไม่มีในทะเบียนชุดนี้ -> Resigned (ไม่ลบ เก็บประวัติไว้)
--   4) PassWork.xlsx : เอกสาร 79 คน
-- วิธีใช้ : phpMyAdmin http://192.168.100.12:8080 -> ฐาน OEE -> แท็บ Import -> เลือกไฟล์นี้ -> Go  (รันซ้ำได้)
-- ============================================================================

SET NAMES utf8mb4;

CREATE TABLE IF NOT EXISTS hr_employee (
                              id            INT UNSIGNED NOT NULL AUTO_INCREMENT,
                              emp_code      VARCHAR(20)  NOT NULL COMMENT 'รหัสพนักงาน เช่น U-0002',
                              emp_group     VARCHAR(40)  NULL COMMENT 'UBG / DMM / นักศึกษา ...',
                              prefix        VARCHAR(20)  NULL COMMENT 'นาย / นาง / นางสาว',
                              name_th       VARCHAR(120) NULL,
                              name_en       VARCHAR(120) NULL,
                              nickname      VARCHAR(40)  NULL,
                              gender        VARCHAR(1)   NULL COMMENT 'M / F',
                              nationality   VARCHAR(40)  NULL,
                              department    VARCHAR(60)  NULL COMMENT 'แผนก / Process',
                              position      VARCHAR(120) NULL COMMENT 'ตำแหน่ง',
                              emp_type      VARCHAR(20)  NULL COMMENT 'Regular / Temporary / Student',
                              start_date    DATE         NULL,
                              contract_end  DATE         NULL,
                              locker_no     VARCHAR(20)  NULL,
                              phone         VARCHAR(40)  NULL,
                              id_card       VARCHAR(30)  NULL COMMENT 'เลขบัตรประชาชน / Passport / Work permit',
                              birth_date    DATE         NULL,
                              address       VARCHAR(300) NULL,
                              status        VARCHAR(20)  NOT NULL DEFAULT 'Active' COMMENT 'Active / Resigned',
                              resign_date   DATE         NULL,
                              remark        VARCHAR(500) NULL,
                              passport_no   VARCHAR(30)  NULL,
                              passport_exp  DATE         NULL,
                              visa_exp      DATE         NULL,
                              permit_type   VARCHAR(60)  NULL COMMENT 'ประเภทใบอนุญาต เช่น มติ 24 ก.ย. 67',
                              wp_no         VARCHAR(30)  NULL COMMENT 'เลขใบอนุญาตทำงาน',
                              wp_exp        DATE         NULL,
                              pink_no       VARCHAR(30)  NULL COMMENT 'เลขบัตรชมพู',
                              pink_exp      DATE         NULL,
                              created_at    DATETIME     NULL,
                              created_by    VARCHAR(40)  NULL,
                              updated_at    DATETIME     NULL,
                              updated_by    VARCHAR(40)  NULL,
                              updated_ip    VARCHAR(45)  NULL,
                              PRIMARY KEY (id),
                              UNIQUE KEY ux_emp_code (emp_code),
                              KEY ix_dept (department),
                              KEY ix_status (status)
                           ) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4;

CREATE TABLE IF NOT EXISTS hr_log (
                              id        BIGINT UNSIGNED NOT NULL AUTO_INCREMENT,
                              at        DATETIME     NOT NULL,
                              username  VARCHAR(40)  NULL,
                              action    VARCHAR(30)  NOT NULL,
                              ref       VARCHAR(40)  NULL,
                              detail    VARCHAR(1000) NULL,
                              ip        VARCHAR(45)  NULL,
                              PRIMARY KEY (id),
                              KEY ix_at (at),
                              KEY ix_ref (ref)
                           ) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4;

-- ---- 1) คอลัมน์เอกสาร (ใช้ได้ทั้ง MySQL และ MariaDB)
SET @s = (SELECT IF(COUNT(*) = 0, 'ALTER TABLE hr_employee ADD COLUMN passport_no VARCHAR(30) NULL', 'DO 0') FROM information_schema.COLUMNS WHERE TABLE_SCHEMA = DATABASE() AND TABLE_NAME = 'hr_employee' AND COLUMN_NAME = 'passport_no');
PREPARE st FROM @s; EXECUTE st; DEALLOCATE PREPARE st;
SET @s = (SELECT IF(COUNT(*) = 0, 'ALTER TABLE hr_employee ADD COLUMN passport_exp DATE NULL', 'DO 0') FROM information_schema.COLUMNS WHERE TABLE_SCHEMA = DATABASE() AND TABLE_NAME = 'hr_employee' AND COLUMN_NAME = 'passport_exp');
PREPARE st FROM @s; EXECUTE st; DEALLOCATE PREPARE st;
SET @s = (SELECT IF(COUNT(*) = 0, 'ALTER TABLE hr_employee ADD COLUMN visa_exp DATE NULL', 'DO 0') FROM information_schema.COLUMNS WHERE TABLE_SCHEMA = DATABASE() AND TABLE_NAME = 'hr_employee' AND COLUMN_NAME = 'visa_exp');
PREPARE st FROM @s; EXECUTE st; DEALLOCATE PREPARE st;
SET @s = (SELECT IF(COUNT(*) = 0, 'ALTER TABLE hr_employee ADD COLUMN permit_type VARCHAR(60) NULL', 'DO 0') FROM information_schema.COLUMNS WHERE TABLE_SCHEMA = DATABASE() AND TABLE_NAME = 'hr_employee' AND COLUMN_NAME = 'permit_type');
PREPARE st FROM @s; EXECUTE st; DEALLOCATE PREPARE st;
SET @s = (SELECT IF(COUNT(*) = 0, 'ALTER TABLE hr_employee ADD COLUMN wp_no VARCHAR(30) NULL', 'DO 0') FROM information_schema.COLUMNS WHERE TABLE_SCHEMA = DATABASE() AND TABLE_NAME = 'hr_employee' AND COLUMN_NAME = 'wp_no');
PREPARE st FROM @s; EXECUTE st; DEALLOCATE PREPARE st;
SET @s = (SELECT IF(COUNT(*) = 0, 'ALTER TABLE hr_employee ADD COLUMN wp_exp DATE NULL', 'DO 0') FROM information_schema.COLUMNS WHERE TABLE_SCHEMA = DATABASE() AND TABLE_NAME = 'hr_employee' AND COLUMN_NAME = 'wp_exp');
PREPARE st FROM @s; EXECUTE st; DEALLOCATE PREPARE st;
SET @s = (SELECT IF(COUNT(*) = 0, 'ALTER TABLE hr_employee ADD COLUMN pink_no VARCHAR(30) NULL', 'DO 0') FROM information_schema.COLUMNS WHERE TABLE_SCHEMA = DATABASE() AND TABLE_NAME = 'hr_employee' AND COLUMN_NAME = 'pink_no');
PREPARE st FROM @s; EXECUTE st; DEALLOCATE PREPARE st;
SET @s = (SELECT IF(COUNT(*) = 0, 'ALTER TABLE hr_employee ADD COLUMN pink_exp DATE NULL', 'DO 0') FROM information_schema.COLUMNS WHERE TABLE_SCHEMA = DATABASE() AND TABLE_NAME = 'hr_employee' AND COLUMN_NAME = 'pink_exp');
PREPARE st FROM @s; EXECUTE st; DEALLOCATE PREPARE st;

-- ---- 2) ทะเบียนพนักงาน
ON DUPLICATE KEY UPDATE emp_group = VALUES(emp_group), prefix = VALUES(prefix), name_th = VALUES(name_th), name_en = VALUES(name_en), nickname = VALUES(nickname), gender = VALUES(gender), nationality = VALUES(nationality), department = VALUES(department), position = VALUES(position), emp_type = VALUES(emp_type), start_date = VALUES(start_date), contract_end = VALUES(contract_end), locker_no = VALUES(locker_no), phone = VALUES(phone), id_card = VALUES(id_card), birth_date = VALUES(birth_date), address = VALUES(address), status = VALUES(status), resign_date = VALUES(resign_date), remark = VALUES(remark), updated_at = NOW(), updated_by = 'import';

-- ---- 3) ไม่มีในทะเบียนชุดนี้ = ลาออก
